<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { ArrowLeft, CopyDocument, Delete, Document, Download, Folder, FullScreen, HomeFilled, Refresh, Setting, Upload } from '@element-plus/icons-vue'
import { parse, stringify } from 'yaml'
import { Terminal } from 'xterm'
import { FitAddon } from 'xterm-addon-fit'
import 'xterm/css/xterm.css'
import KubernetesYamlEditor from '@/components/KubernetesYamlEditor.vue'
import { applyKubernetesObject, deleteKubernetesObject, downloadKubernetesPodFile, execKubernetesPodCommand, getKubernetesObject, getKubernetesPodLogs, listKubernetesEvents, listKubernetesObjects, listKubernetesPodFiles, uploadKubernetesPodFile, type KubernetesEvent, type KubernetesObject, type KubernetesPodFile } from '@/api/kubernetes'

const route = useRoute(), router = useRouter()
const clusterID = computed(() => Number(route.query.cluster_id || 0)), namespace = computed(() => String(route.query.namespace || 'default')), name = computed(() => String(route.query.name || ''))
const loading = ref(false), activeTab = ref('overview'), yaml = ref(''), manifest = ref<any>({}), row = ref<KubernetesObject | null>(null), events = ref<KubernetesEvent[]>([])
const describeDialog = ref(false), cloneDialog = ref(false), cloneYaml = ref(''), saving = ref(false), deleteDialog = ref(false), deleting = ref(false), deleteConfirm = ref('')
const expandedContainers = ref<Record<string, boolean>>({})
const logs = ref(''), logsLoading = ref(false), logFilter = ref(''), logTailLines = ref(100), logTimestamps = ref(false), logFontSize = ref(12), logWrap = ref(false), logPanel = ref<HTMLElement>()
const terminalHost = ref<HTMLElement>(), terminalPanel = ref<HTMLElement>(), terminalFontSize = ref(12), terminalBuffer = ref(''), commandRunning = ref(false)
const filePath = ref('/'), fileContainer = ref(''), files = ref<KubernetesPodFile[]>([]), filesLoading = ref(false), uploadInput = ref<HTMLInputElement>()
let xterm: Terminal | undefined, xtermFit: FitAddon | undefined, resizeObserver: ResizeObserver | undefined

const metadata = computed(() => manifest.value?.metadata || {}), spec = computed(() => manifest.value?.spec || {}), status = computed(() => manifest.value?.status || {})
const containers = computed<any[]>(() => spec.value?.containers || []), containerStatuses = computed<any[]>(() => status.value?.containerStatuses || [])
const labels = computed<Record<string,string>>(() => metadata.value?.labels || {}), volumes = computed<any[]>(() => spec.value?.volumes || [])
const podEvents = computed(() => events.value.filter(item => item.involvedObject.kind.toLowerCase() === 'pod' && item.involvedObject.name === name.value))
const filteredLogs = computed(() => logs.value.split('\n').filter(line => !logFilter.value || line.toLowerCase().includes(logFilter.value.toLowerCase())).join('\n'))
const readyCount = computed(() => containerStatuses.value.filter(item => item.ready).length)
const restartCount = computed(() => containerStatuses.value.reduce((sum, item) => sum + Number(item.restartCount || 0), 0))
const owner = computed(() => metadata.value?.ownerReferences?.[0] ? `${metadata.value.ownerReferences[0].kind}/${metadata.value.ownerReferences[0].name}` : '-')
const primaryContainer = computed(() => containers.value[0]?.name || '')
function containerStatus(name: string) { return containerStatuses.value.find(item => item.name === name) }
function containerState(name: string) { const state = containerStatus(name)?.state || {}; const type = Object.keys(state)[0] || 'waiting'; return { type, detail: state[type] || {} } }
function stateLabel(name: string) { const type = containerState(name).type; return type === 'running' ? 'Running' : type === 'terminated' ? 'Terminated' : 'Waiting' }
function stateTime(name: string) { const detail = containerState(name).detail; return detail.startedAt || detail.finishedAt || '' }
function isContainerExpanded(name: string) { return expandedContainers.value[name] !== false }
function toggleContainer(name: string) { expandedContainers.value[name] = !isContainerExpanded(name) }
const description = computed(() => [
  `Name:                   ${name.value}`, `Namespace:              ${namespace.value}`, `Priority:               ${spec.value.priority || 0}`,
  `Service Account:       ${spec.value.serviceAccountName || 'default'}`, `Node:                   ${spec.value.nodeName || row.value?.node || '-'}`,
  `Start Time:            ${status.value.startTime || '-'}`, `Labels:                 ${Object.entries(labels.value).map(([k,v]) => `${k}=${v}`).join(', ') || '<none>'}`,
  `Annotations:           ${Object.entries(metadata.value?.annotations || {}).map(([k,v]) => `${k}=${v}`).join(', ') || '<none>'}`,
  `Status:                 ${status.value.phase || row.value?.status || '-'}`, `IP:                     ${status.value.podIP || row.value?.pod_ip || '-'}`,
  `Controlled By:         ${owner.value}`, 'Containers:', ...containers.value.flatMap(container => { const state = containerStatuses.value.find(item => item.name === container.name); return [`  ${container.name}:`, `    Image:                ${container.image}`, `    Ready:                ${state?.ready ?? false}`, `    Restart Count:        ${state?.restartCount || 0}`] }),
  'Events:', ...(podEvents.value.length ? podEvents.value.map(item => `  ${item.type}\t${item.reason}\t${item.lastTimestamp}\t${item.message}`) : ['  <none>']),
].join('\n'))

async function load() {
  if (!clusterID.value || !name.value) return
  loading.value = true
  try {
    const [detail, pods, eventResult] = await Promise.all([
      getKubernetesObject({ cluster_id: clusterID.value, resource: 'pods', namespace: namespace.value, name: name.value }),
      listKubernetesObjects({ cluster_id: clusterID.value, resource: 'pods', namespace: namespace.value, keyword: name.value, page: 1, limit: 100 }),
      listKubernetesEvents(clusterID.value, namespace.value),
    ])
    yaml.value = detail.data.data.yaml; manifest.value = parse(yaml.value) || {}; row.value = pods.data.data.list.find(item => item.name === name.value) || null; events.value = eventResult.data.data.list; if (!fileContainer.value) fileContainer.value = containers.value[0]?.name || ''
  } finally { loading.value = false }
}
async function loadLogs() { if (!primaryContainer.value) return; logsLoading.value = true; try { const result = await getKubernetesPodLogs({ cluster_id: clusterID.value, namespace: namespace.value, pod: name.value, container: primaryContainer.value, tail_lines: logTailLines.value, timestamps: logTimestamps.value }); logs.value = result.data.data.logs || '' } finally { logsLoading.value = false } }
async function loadFiles() { if (!fileContainer.value) return; filesLoading.value=true; try { const result=await listKubernetesPodFiles({cluster_id:clusterID.value,namespace:namespace.value,pod:name.value,container:fileContainer.value,path:filePath.value}); files.value=result.data.data.list } finally { filesLoading.value=false } }
function openFile(item:KubernetesPodFile){if(item.directory){filePath.value=item.path;void loadFiles()}else void downloadFile(item)}
function fileUp(){if(filePath.value==='/')return;filePath.value=filePath.value.split('/').slice(0,-1).join('/')||'/';void loadFiles()}
async function uploadFile(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;await uploadKubernetesPodFile({cluster_id:clusterID.value,namespace:namespace.value,pod:name.value,container:fileContainer.value,path:filePath.value},file);input.value='';ElMessage.success('上传成功');await loadFiles()}
async function downloadFile(item:KubernetesPodFile){const response=await downloadKubernetesPodFile({cluster_id:clusterID.value,namespace:namespace.value,pod:name.value,container:fileContainer.value,path:item.path});const link=document.createElement('a');link.href=URL.createObjectURL(response.data);link.download=item.name;link.click();URL.revokeObjectURL(link.href)}
function openClone() { const object = parse(yaml.value); object.metadata.name = `${name.value}-copy`; delete object.metadata.uid; delete object.metadata.resourceVersion; delete object.metadata.creationTimestamp; delete object.metadata.ownerReferences; delete object.status; cloneYaml.value = stringify(object); cloneDialog.value = true }
async function saveClone() { saving.value = true; try { const object = parse(cloneYaml.value); await applyKubernetesObject({ cluster_id: clusterID.value, resource: 'pods', namespace: object?.metadata?.namespace || namespace.value, yaml: cloneYaml.value }); cloneDialog.value = false; ElMessage.success('Pod 已克隆') } finally { saving.value = false } }
function openDelete() { deleteConfirm.value = ''; deleteDialog.value = true }
async function remove() { deleting.value = true; try { await deleteKubernetesObject({ cluster_id: clusterID.value, resource: 'pods', namespace: namespace.value, name: name.value, wait: true }); ElMessage.success('删除成功'); await router.push('/kubernetes/workloads') } finally { deleting.value = false } }
async function initTerminal() { await nextTick(); if (!terminalHost.value || xterm) { xtermFit?.fit(); return }; xterm = new Terminal({ cursorBlink:true, fontSize:terminalFontSize.value, lineHeight:1.25, fontFamily:'ui-monospace,SFMono-Regular,Menlo,monospace', theme:{background:'#050505',foreground:'#e7eaf0',cursor:'#fff'}, scrollback:5000 }); xtermFit = new FitAddon(); xterm.loadAddon(xtermFit); xterm.open(terminalHost.value); xtermFit.fit(); xterm.write('\x1b[32m$ \x1b[0m'); xterm.onData(data => { if (commandRunning.value) return; if (data === '\r') { const command = terminalBuffer.value; terminalBuffer.value=''; void runCommand(command); return }; if (data === '\u007f') { if (terminalBuffer.value) { terminalBuffer.value=terminalBuffer.value.slice(0,-1); xterm?.write('\b \b') }; return }; if (data >= ' ') { terminalBuffer.value += data; xterm?.write(data) } }); resizeObserver = new ResizeObserver(() => xtermFit?.fit()); resizeObserver.observe(terminalHost.value) }
async function runCommand(command:string) { if (!command.trim() || !primaryContainer.value || !xterm) { xterm?.write('\r\n$ '); return }; commandRunning.value=true; try { const result=await execKubernetesPodCommand({cluster_id:clusterID.value,namespace:namespace.value,pod:name.value,container:primaryContainer.value,command}); const output=`${result.data.data.output || ''}${result.data.data.error || ''}`; xterm.write(`\r\n${output.replace(/\n/g,'\r\n')}${output && !output.endsWith('\n')?'\r\n':''}$ `) } finally { commandRunning.value=false } }
function downloadLogs(){const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([filteredLogs.value],{type:'text/plain;charset=utf-8'}));link.download=`${name.value}.log`;link.click();URL.revokeObjectURL(link.href)}
async function fullscreen(target:HTMLElement|undefined){if(!target)return;if(document.fullscreenElement)await document.exitFullscreen();else await target.requestFullscreen();await nextTick();xtermFit?.fit()}
watch(activeTab, value => { if(value==='logs'&&!logs.value)void loadLogs();if(value==='terminal')void initTerminal();if(value==='files')void loadFiles() }); watch(terminalFontSize,value=>{if(xterm)xterm.options.fontSize=value;xtermFit?.fit()}); onMounted(load); onBeforeUnmount(()=>{resizeObserver?.disconnect();xterm?.dispose()})
</script>

<template>
  <section v-loading="loading" class="pod-detail">
    <header class="page-head"><div class="identity"><el-button text :icon="ArrowLeft" @click="router.back()"/><div><h1>{{ name }}</h1><p>Namespace: <b>{{ namespace }}</b></p></div></div><div class="actions"><el-button :icon="Refresh" @click="load">刷新</el-button><el-button :icon="Document" @click="describeDialog=true">描述</el-button><el-button :icon="CopyDocument" @click="openClone">克隆</el-button><el-button type="danger" :icon="Delete" @click="openDelete">删除</el-button></div></header>
    <el-tabs v-model="activeTab" class="tabs">
      <el-tab-pane label="概览" name="overview"><div class="metrics"><article><span>状态</span><strong class="ok">● {{ row?.status || status.phase || '-' }}</strong><small>{{ status.phase || '-' }}</small></article><article><span>就绪</span><strong>{{ readyCount }}/{{ containers.length }}</strong><small>容器</small></article><article><span>重启次数</span><strong>{{ restartCount }}</strong><small>所有容器</small></article><article><span>节点</span><strong class="link">{{ row?.node || spec.nodeName || '-' }}</strong></article><article><span>IP</span><strong>{{ row?.pod_ip || status.podIP || '-' }}</strong><small>Pod IP</small></article><article><span>创建时间</span><strong>{{ row?.age || '-' }}</strong><small>{{ row?.created_at || '-' }}</small></article></div><div class="overview"><main><section class="panel"><h2>容器 ({{ containers.length }})</h2><div class="container-head"><b>容器</b><b>状态</b><b>重启</b><b>镜像</b></div><div v-for="container in containers" :key="container.name" class="container-row"><span><b>{{ container.name }}</b><small>{{ container.image }}</small></span><span class="ok">● {{ containerStatuses.find(item=>item.name===container.name)?.ready?'运行中':'未就绪' }}</span><span>{{ containerStatuses.find(item=>item.name===container.name)?.restartCount || 0 }}</span><code>{{ container.image }}</code></div></section><section class="panel info"><h2>信息</h2><div><span>所有者</span><b class="link">{{ owner }}</b><span>启动时间</span><b>{{ status.startTime || '-' }}</b><span>服务账号</span><b>{{ spec.serviceAccountName || 'default' }}</b><span>QoS 类</span><b>{{ status.qosClass || '-' }}</b><span>重启策略</span><b>{{ spec.restartPolicy || '-' }}</b><span>DNS 策略</span><b>{{ spec.dnsPolicy || '-' }}</b><span>终止宽限期</span><b>{{ spec.terminationGracePeriodSeconds ?? '-' }}s</b><span>卷</span><b>{{ volumes.length }}</b></div><footer><span>UID</span><code>{{ metadata.uid || '-' }}</code></footer></section></main><aside><section class="panel"><h2>事件 ({{ podEvents.length }})</h2><div v-for="item in podEvents.slice(0,5)" :key="`${item.reason}-${item.lastTimestamp}`" class="event"><b :class="{warn:item.type==='Warning'}">{{ item.reason }}</b><span>{{ item.message }}</span><small>{{ item.lastTimestamp }}</small></div><p v-if="!podEvents.length">暂无事件</p></section><section class="panel"><h2>卷 ({{ volumes.length }})</h2><div v-for="volume in volumes" :key="volume.name" class="resource"><b>{{ volume.name }}</b><span>{{ Object.keys(volume).find(key=>key!=='name') || '-' }}</span></div></section><section class="panel"><h2>标签 ({{ Object.keys(labels).length }})</h2><code v-for="(value,key) in labels" :key="key" class="tag">{{ key }}={{ value }}</code></section></aside></div></el-tab-pane>
      <el-tab-pane :label="`容器 (${containers.length})`" name="containers"><section class="pod-containers"><article v-for="container in containers" :key="container.name" class="pod-container-card"><header><b>{{ container.name }}</b><div><span :class="{ ready: containerStatus(container.name)?.ready }">{{ containerStatus(container.name)?.ready ? 'Ready' : 'Not Ready' }}</span><em>{{ containerStatus(container.name)?.restartCount || 0 }} restarts</em></div></header><div class="container-summary"><section><span>IMAGE</span><code>{{ container.image }}</code></section><section><span>IMAGE PULL POLICY</span><code>{{ container.imagePullPolicy || '-' }}</code></section><section class="state"><span>STATE</span><div><b :class="containerState(container.name).type">{{ stateLabel(container.name) }}</b><small v-if="stateTime(container.name)">since {{ stateTime(container.name) }}</small></div></section></div><button class="container-toggle" @click="toggleContainer(container.name)">{{ isContainerExpanded(container.name) ? '⌃ 收起' : '⌄ 展开更多' }}</button><div v-if="isContainerExpanded(container.name)" class="container-details"><section><span>PORTS</span><div class="ports"><template v-for="port in container.ports || []" :key="`${port.containerPort}-${port.protocol}`"><code>{{ port.containerPort }}</code><small>{{ port.protocol || 'TCP' }}</small></template><small v-if="!container.ports?.length">未配置</small></div></section><section><span>VOLUME MOUNTS（{{ container.volumeMounts?.length || 0 }}）</span><div class="mounts"><div v-for="mount in container.volumeMounts || []" :key="`${mount.name}-${mount.mountPath}`"><code>{{ mount.name }}</code><b>{{ mount.mountPath }}</b><small v-if="mount.readOnly">RO</small></div><small v-if="!container.volumeMounts?.length">未配置</small></div></section><section class="ids"><div><span>IMAGE ID</span><code>{{ containerStatus(container.name)?.imageID || '-' }}</code></div><div><span>CONTAINER ID</span><code>{{ containerStatus(container.name)?.containerID || '-' }}</code></div></section></div></article><el-empty v-if="!containers.length" description="暂无容器" /></section></el-tab-pane>
      <el-tab-pane label="YAML" name="yaml"><KubernetesYamlEditor :model-value="yaml" min-height="calc(100vh - 210px)" readonly/></el-tab-pane>
      <el-tab-pane label="日志" name="logs"><section ref="logPanel" class="console-panel"><header><b>Logs</b><el-input v-model="logFilter" placeholder="过滤日志…" clearable/><el-popover placement="bottom-end" :width="260" trigger="click"><template #reference><el-button :icon="Setting"/></template><div class="settings"><label>Tail Lines<el-select v-model="logTailLines" @change="loadLogs"><el-option label="100" :value="100"/><el-option label="500" :value="500"/><el-option label="全部" :value="0"/></el-select></label><label>显示时间戳<el-switch v-model="logTimestamps" @change="loadLogs"/></label><label>字体大小<el-input-number v-model="logFontSize" :min="10" :max="24"/></label></div></el-popover><el-button title="自动换行" :class="{active:logWrap}" @click="logWrap=!logWrap">↵</el-button><el-button title="清屏" @click="logs=''">≡</el-button><el-button :icon="Download" @click="downloadLogs"/><el-button :icon="FullScreen" @click="fullscreen(logPanel)"/></header><pre :class="{wrap:logWrap}" :style="{fontSize:`${logFontSize}px`}">{{ filteredLogs || (logsLoading?'加载中…':'暂无日志') }}</pre></section></el-tab-pane>
      <el-tab-pane label="终端" name="terminal"><section ref="terminalPanel" class="console-panel terminal"><header><b>&gt;_ Terminal</b><el-popover placement="bottom-end" :width="220" trigger="click"><template #reference><el-button :icon="Setting"/></template><div class="settings"><label>字体大小<el-input-number v-model="terminalFontSize" :min="10" :max="24"/></label></div></el-popover><el-button title="清屏" @click="xterm?.clear()">≡</el-button><el-button :icon="FullScreen" @click="fullscreen(terminalPanel)"/></header><div ref="terminalHost" class="terminal-host"/></section></el-tab-pane>
      <el-tab-pane label="文件" name="files"><section v-loading="filesLoading" class="files-panel"><header><el-select :model-value="primaryContainer"><el-option v-for="container in containers" :key="container.name" :label="container.name" :value="container.name"/></el-select><el-button :icon="ArrowLeft" :disabled="filePath==='/'" @click="fileUp"/><el-button :icon="HomeFilled" @click="filePath='/';loadFiles()"/><el-input v-model="filePath" @keyup.enter="loadFiles"/><el-button :icon="Refresh" @click="loadFiles"/><el-button type="primary" :icon="Upload" @click="uploadInput?.click()">上传</el-button><input ref="uploadInput" type="file" hidden @change="uploadFile"/></header><div class="file-table"><div class="file-head"><b>名称</b><b>UID</b><b>GID</b><b>大小</b><b>权限</b><b>修改时间</b><b>操作</b></div><div v-for="item in files" :key="item.path" class="file-row"><span class="file-name" @dblclick="openFile(item)"><el-icon><Folder v-if="item.directory"/><Document v-else/></el-icon><b>{{ item.name }}</b></span><code>{{ item.uid }}</code><code>{{ item.gid }}</code><span>{{ item.directory ? '-' : `${(item.size/1024).toFixed(1)}K` }}</span><code>{{ item.mode }}</code><span>{{ new Date(item.modified_at*1000).toLocaleString() }}</span><el-button v-if="!item.directory" text :icon="Download" @click="downloadFile(item)"/></div><el-empty v-if="!files.length" description="目录为空" :image-size="54"/></div></section></el-tab-pane>
      <el-tab-pane :label="`卷 (${volumes.length})`" name="volumes"><section class="volumes-panel"><h2>Volumes</h2><div class="volume-head"><b>Name</b><b>Type</b><b>Details</b><b>Volume Mounts</b></div><div v-for="volume in volumes" :key="volume.name" class="volume-row"><b>{{ volume.name }}</b><code>{{ Object.keys(volume).find(key=>key!=='name') || '-' }}</code><span>{{ volume.persistentVolumeClaim?.claimName || volume.configMap?.name || volume.secret?.secretName || 'N/A' }}</span><div><template v-for="container in containers" :key="container.name"><span v-for="mount in (container.volumeMounts||[]).filter((item:any)=>item.name===volume.name)" :key="`${container.name}-${mount.mountPath}`"><b>{{ container.name }}</b> → <code>{{ mount.mountPath }}</code><small v-if="mount.readOnly">RO</small></span></template><span v-if="!containers.some(container=>(container.volumeMounts||[]).some((item:any)=>item.name===volume.name))">未挂载</span></div></div><el-empty v-if="!volumes.length" description="暂无卷"/></section></el-tab-pane>
      <el-tab-pane :label="`事件 (${podEvents.length})`" name="events"><section class="panel"><div v-for="item in podEvents" :key="`${item.reason}-${item.lastTimestamp}`" class="event-row"><b>{{ item.type }}</b><span>{{ item.reason }}</span><span>{{ item.message }}</span><span>{{ item.lastTimestamp }}</span></div></section></el-tab-pane>
    </el-tabs>
    <el-dialog v-model="describeDialog" title="Pod 描述" width="min(800px,calc(100vw - 32px))" align-center><div class="command">kubectl describe pod -n {{ namespace }} {{ name }}</div><pre class="description">{{ description }}</pre></el-dialog>
    <el-dialog v-model="cloneDialog" title="克隆 Pod" width="min(800px,calc(100vw - 32px))" align-center destroy-on-close><KubernetesYamlEditor v-model="cloneYaml"/><template #footer><el-button @click="cloneDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveClone">创建副本</el-button></template></el-dialog>
    <el-dialog v-model="deleteDialog" title="删除 Pod" width="min(460px,calc(100vw - 32px))" align-center><p>删除后不可恢复，请输入 <b>{{ name }}</b> 确认。</p><el-input v-model="deleteConfirm" :placeholder="name"/><template #footer><el-button @click="deleteDialog=false">取消</el-button><el-button type="danger" :loading="deleting" :disabled="deleteConfirm!==name" @click="remove">删除</el-button></template></el-dialog>
  </section>
</template>

